// app/components/MainLayout.tsx
"use client";

import { useState } from "react";
import { usePathname } from "next/navigation";
import Header from "./Header";
import LeftSide from "./LeftSide";
import { RightSideTop, RightSideBottom } from "./RightSide";


export default function MainLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const isAuthPage = pathname === "/login" || pathname === "/register";
  const isChatRoute = pathname === "/chat" || pathname.startsWith("/chat/");

  const [isChatMode, setIsChatMode] = useState(false);
  const effectiveChatMode = isChatMode || isChatRoute;

  if (isAuthPage) {
    return <main className="auth-mode">{children}</main>;
  }

  return (
    <div className="c-chat">
      <Header toggleChat={() => setIsChatMode(!effectiveChatMode)} isChatMode={effectiveChatMode} />

      <div className="main-content">
        <LeftSide isChatMode={effectiveChatMode} />

        <main className="nervna-router">
          {children}
        </main>

        {/* RIGHT SIDE WRAPPER */}
        <div className="right-side">
          <RightSideTop />
          <RightSideBottom />
        </div>
      </div>
    </div>
  );
}
